CREATE TABLE [dbo].[ccDNIS](	  [dni_id] SMALLINT NOT NULL	, [dni_numero] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [dni_tipo] TINYINT NULL	, [tipodni_id] INT NOT NULL	, [dni_tpoMaxEspera] SMALLINT NOT NULL	, [dni_Descripcion] VARCHAR(40) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [dni_Status] BIT NOT NULL DEFAULT((1))	, [dni_isBlock] BIT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_ccDNIS] PRIMARY KEY ([dni_id] ASC))CREATE NONCLUSTERED INDEX [IX_ccDNIS] ON [dbo].[ccDNIS] ([dni_numero] ASC, [dni_Status] ASC)